<?php
function requestVisible($r){$u=auth();departmentAccess($r['department_id']);if($u['role']==='STUDENT'&&$r['student_id']!==$u['student_id'])fail('You can only view your own requests.',403);}
function portalRequest($id){$r=one('SELECT * FROM portal_requests WHERE id=?',[$id])??fail('Request not found.',404);requestVisible($r);return $r;}
if($path==='/portal/requests'&&$method==='GET'){
 $u=auth();$sql='SELECT pr.*,s.full_name student_name,s.roll_no,d.name department_name FROM portal_requests pr JOIN students s ON s.id=pr.student_id JOIN departments d ON d.id=pr.department_id WHERE 1=1';$p=[];scopeSql($sql,$p,'pr.department_id');if($u['role']==='STUDENT'){$sql.=' AND pr.student_id=?';$p[]=$u['student_id'];}filterSql($sql,$p,['kind'=>'pr.kind','status'=>'pr.status'],$q);
 $list=rows($sql.' ORDER BY pr.created_at DESC,pr.id DESC',$p);foreach($list as &$r){$r['remarks']=rows('SELECT rr.*,u.full_name author_name,u.role author_role FROM portal_request_remarks rr JOIN users u ON u.id=rr.author_id WHERE request_id=? ORDER BY rr.created_at,rr.id',[$r['id']]);}unset($r);send(['requests'=>$list]);
}
if($path==='/portal/requests'&&$method==='POST'){
 $u=role('STUDENT');need($body,['kind','title','description']);if(!in_array($body['kind'],['LEAVE','COMPLAINT']))fail('Invalid request type.');$st=student($u['student_id']);$title=boundedText($body['title'],'Title',191);$desc=boundedText($body['description'],'Description');$start=null;$end=null;
 if($body['kind']==='LEAVE'){need($body,['start_date','end_date']);validateDate($body['start_date']);validateDate($body['end_date']);$start=$body['start_date'];$end=$body['end_date'];if($start>$end)fail('End date must be after start date.');}
 $id=uid('req-');transaction(function()use($id,$u,$st,$body,$title,$desc,$start,$end){if($body['kind']==='LEAVE'){query('SELECT id FROM students WHERE id=? FOR UPDATE',[$st['id']]);if(one("SELECT id FROM portal_requests WHERE student_id=? AND kind='LEAVE' AND status IN ('PENDING','APPROVED') AND start_date<=? AND end_date>=?",[$st['id'],$end,$start]))fail('An overlapping leave request already exists.');}insertRow('portal_requests',['id'=>$id,'kind'=>$body['kind'],'student_id'=>$st['id'],'department_id'=>$st['department_id'],'title'=>$title,'description'=>$desc,'start_date'=>$start,'end_date'=>$end,'created_by'=>$u['id']]);});send(['success'=>true,'id'=>$id],201);
}
if(preg_match('#^/portal/requests/([^/]+)/review$#',$path,$m)&&$method==='POST'){
 $u=role();need($body,['status','remark']);$remark=boundedText($body['remark'],'Remark');transaction(function()use($m,$body,$remark,$u){$r=one('SELECT * FROM portal_requests WHERE id=? FOR UPDATE',[$m[1]])??fail('Request not found.',404);requestVisible($r);$status=$body['status'];$allowed=$r['kind']==='LEAVE'?['PENDING'=>['PENDING','APPROVED','REJECTED']]:['PENDING'=>['PENDING','IN_REVIEW','RESOLVED'],'IN_REVIEW'=>['IN_REVIEW','RESOLVED'],'RESOLVED'=>['RESOLVED','IN_REVIEW']];if(!in_array($status,$allowed[$r['status']]??[$r['status']],true))fail('This status transition is not allowed.');if($r['kind']==='LEAVE'&&$r['status']!=='PENDING'&&$status!==$r['status'])fail('This leave request has already been decided.');updateRow('portal_requests',$r['id'],['status'=>$status,'updated_at'=>gmdate('Y-m-d H:i:s')]);insertRow('portal_request_remarks',['id'=>uid(),'request_id'=>$r['id'],'author_id'=>$u['id'],'remark'=>$remark,'new_status'=>$status]);});send(['success'=>true]);
}
if(preg_match('#^/portal/requests/([^/]+)/cancel$#',$path,$m)&&$method==='POST'){
 role('STUDENT');transaction(function()use($m){$r=one('SELECT * FROM portal_requests WHERE id=? FOR UPDATE',[$m[1]])??fail('Request not found.',404);requestVisible($r);if($r['kind']!=='LEAVE'||$r['status']!=='PENDING')fail('Only pending leave can be cancelled.');updateRow('portal_requests',$r['id'],['status'=>'CANCELLED','updated_at'=>gmdate('Y-m-d H:i:s')]);});send(['success'=>true]);
}
if($path==='/reports/attendance'&&$method==='GET'){
 $u=auth();$period=$q['period']??'MONTHLY';if(!in_array($period,['WEEKLY','MONTHLY','SEMESTER','CUSTOM']))fail('Invalid report period.');$anchor=$q['anchor_date']??(new DateTime('now',new DateTimeZone('Asia/Kolkata')))->format('Y-m-d');validateDate($anchor);$dt=new DateTimeImmutable($anchor);
 if($period==='WEEKLY'){$start=$dt->modify('-'.((int)$dt->format('N')-1).' days')->format('Y-m-d');$end=(new DateTimeImmutable($start))->modify('+6 days')->format('Y-m-d');}
 elseif($period==='MONTHLY'){$start=$dt->format('Y-m-01');$end=$dt->format('Y-m-t');}
 else{need($q,['start_date','end_date']);$start=$q['start_date'];$end=$q['end_date'];validateDate($start);validateDate($end);if($start>$end)fail('Invalid date range.');}
 $filters=['start_date'=>$start,'end_date'=>$end];foreach(['division_id','subject_id'] as $k)if(!empty($q[$k]))$filters[$k]=$q[$k];
 if($u['role']==='STUDENT'){$students=[student($u['student_id'])];$filters['division_id']=$students[0]['division_id'];}else{role();$students=studentRows($filters);}
 $sessions=validSessions($filters,true);$list=[];foreach($students as $st){$stats=statsFor($st,$sessions);$ds=array_filter($sessions,fn($x)=>$x['division_id']===$st['division_id']);$ids=array_flip(array_column($ds,'id'));$counts=array_fill_keys(['PRESENT','LATE','ABSENT','LEAVE','EXCUSED'],0);$recorded=0;foreach(rows('SELECT session_id,status FROM attendance_records WHERE student_id=?',[$st['id']]) as $r)if(isset($ids[$r['session_id']])){$recorded++;if(isset($counts[$r['status']]))$counts[$r['status']]++;}$list[]=['student_id'=>$st['id'],'name'=>$st['full_name'],'roll_no'=>$st['roll_no'],'class'=>$st['division_name'],'department'=>$st['department_name'],'unmarked'=>max(0,count($ds)-$recorded),...$counts,...$stats];}
 send(['period'=>$period,'start_date'=>$start,'end_date'=>$end,'rows'=>$list,'thresholds'=>thresholds(),'note'=>'Present and Late count as attended. Approved leave requests do not automatically alter attendance. Unmarked sessions count in the conducted total. Semester dates must be chosen from the college timetable.']);
}
// Optional photo matching is a suggestion only. Human review is mandatory; no sanctions are auto-selected.
if($path==='/discipline/identify'&&$method==='POST'){
 $u=role();need($body,['image_data']);photoBytes($body['image_data']);$s=settings();
 $sql="SELECT st.id student_id,st.roll_no,st.full_name,CASE WHEN fe.status='ENROLLED' AND bc.consent_granted=1 THEN fe.face_embedding ELSE NULL END face_embedding FROM students st JOIN class_divisions cd ON cd.id=st.division_id LEFT JOIN face_enrollments fe ON fe.student_id=st.id LEFT JOIN biometric_consents bc ON bc.student_id=st.id WHERE st.is_active=1";$params=[];scopeSql($sql,$params,'cd.department_id');
 $students=rows($sql.' ORDER BY st.roll_no',$params);$enrolled=array_values(array_filter($students,fn($st)=>!empty($st['face_embedding'])));
 if(!$enrolled)fail('No consented, enrolled faces are available in your search scope. Ask Admin to enroll student faces.');
 $r=engine(['action'=>'scan','image'=>$body['image_data'],'enrolled'=>$enrolled,'threshold'=>(float)$s['face_match_threshold'],'min_quality'=>(float)$s['min_face_quality'],'duplicate_protection'=>true]);if(empty($r['success']))fail($r['message']??'Photo identification failed.');
 $matches=[];$faces=[];$valid=array_flip(array_column($enrolled,'student_id'));$seen=[];
 foreach($r['faces']??[] as $f){$sid=$f['student_id']??null;$detail=['student_id'=>null,'name'=>'Unknown','box'=>$f['box']??null,'is_recognized'=>false];
  if($sid&&isset($valid[$sid])&&!isset($seen[$sid])&&!empty($f['is_recognized'])){$st=student($sid);divisionAccess($st['division_id']);$detail=['student_id'=>$sid,'name'=>$st['full_name'],'roll_no'=>$st['roll_no'],'class'=>$st['division_name'],'branch'=>$st['department_name'],'match_percentage'=>$f['match_percentage']??null,'box'=>$f['box']??null,'is_recognized'=>true];$matches[]=$detail;$seen[$sid]=true;}$faces[]=$detail;
 }
 send(['matches'=>$matches,'faces'=>$faces,'total_faces'=>count($faces),'unknown_faces'=>count($faces)-count($matches),'searched_students'=>count($students),'enrolled_faces'=>count($enrolled),'scope'=>$u['role']==='ADMIN'?'All departments':($u['department_name']??'Your department'),'requires_review'=>true]);
}
if($path==='/discipline'&&$method==='GET'){
 role();$sql='SELECT di.*,u.full_name created_by_name,d.name department_name FROM discipline_incidents di JOIN users u ON u.id=di.created_by JOIN departments d ON d.id=di.department_id WHERE 1=1';$p=[];scopeSql($sql,$p,'di.department_id');$list=rows($sql.' ORDER BY di.incident_date DESC,di.created_at DESC',$p);foreach($list as &$r){$r['students']=rows('SELECT s.id,s.full_name,s.roll_no,CONCAT(cd.year_level,\' \',cd.division) class_name,d.name branch FROM discipline_students ds JOIN students s ON s.id=ds.student_id JOIN class_divisions cd ON cd.id=s.division_id JOIN departments d ON d.id=cd.department_id WHERE ds.incident_id=?',[$r['id']]);}unset($r);send(['incidents'=>$list]);
}
if($path==='/discipline'&&$method==='POST'){
 $u=role();need($body,['division_id','category','incident_date','location','description','action_taken','student_ids']);$d=divisionAccess($body['division_id']);validateDate($body['incident_date']);if(!in_array($body['category'],['CANTEEN','PARKING','GROUP','OTHER']))fail('Invalid incident category.');if(($body['review_confirmed']??false)!==true)fail('Confirm that the student details have been reviewed.');if(!is_array($body['student_ids'])||!count($body['student_ids'])||count($body['student_ids'])>100)fail('Select 1–100 reviewed students.');$ids=array_unique($body['student_ids']);foreach($ids as $sid){$st=student($sid);ownStudent($st);if($st['division_id']!==$d['id']||!$st['is_active'])fail('Choose active students from the selected class.');}
 $id=uid('incident-');$location=boundedText($body['location'],'Location',191);$desc=boundedText($body['description'],'Description');$action=boundedText($body['action_taken'],'Action taken');transaction(function()use($id,$d,$u,$body,$ids,$location,$desc,$action){insertRow('discipline_incidents',['id'=>$id,'department_id'=>$d['department_id'],'category'=>$body['category'],'incident_date'=>$body['incident_date'],'location'=>$location,'description'=>$desc,'action_taken'=>$action,'created_by'=>$u['id']]);foreach($ids as $sid)insertRow('discipline_students',['incident_id'=>$id,'student_id'=>$sid]);});send(['success'=>true,'id'=>$id],201);
}
